PRAGMA foreign_keys=OFF;
DELETE FROM "workspaces";
DELETE FROM "users";
DELETE FROM "pages";
DELETE FROM "databases";
DELETE FROM "database_rows";
DELETE FROM "counters";
DELETE FROM "comments";
DELETE FROM "blocks";
UPDATE database_rows
SET properties_json = json_set(
  properties_json,
  '$.title',
  CASE json_extract(properties_json, '$.source_kind')
    WHEN 'bank record' THEN printf('%s account item from %s (%s)', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'), json_extract(properties_json, '$.status'))
    WHEN 'calendar' THEN printf('Calendar note for %s on %s', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'))
    WHEN 'household note' THEN printf('Sam Taylor note: %s, %s', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'))
    WHEN 'invoice' THEN printf('%s invoice dated %s — %s', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'), json_extract(properties_json, '$.status'))
    WHEN 'official guidance' THEN printf('Source review from %s for %s', json_extract(properties_json, '$.effective_date'), json_extract(properties_json, '$.topic'))
    WHEN 'statement' THEN printf('%s statement item / %s / %s', json_extract(properties_json, '$.effective_date'), json_extract(properties_json, '$.category'), json_extract(properties_json, '$.status'))
    WHEN 'email' THEN printf('%s email received %s (%s)', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'), json_extract(properties_json, '$.status'))
    WHEN 'receipt' THEN printf('Receipt filed for %s on %s', json_extract(properties_json, '$.category'), json_extract(properties_json, '$.effective_date'))
    ELSE json_extract(properties_json, '$.title')
  END,
  '$.topic',
  CASE json_extract(properties_json, '$.topic')
    WHEN 'statement evidence' THEN 'card statement records'
    WHEN 'minimum-only comparison' THEN 'repayment scenarios'
    WHEN 'cashflow capacity' THEN 'monthly cashflow'
    WHEN 'rent protection' THEN 'housing reserve'
    WHEN 'unsafe borrowing rejection' THEN 'funding alternatives'
    WHEN 'payment decision' THEN 'payment review'
    ELSE json_extract(properties_json, '$.topic')
  END
)
WHERE json_extract(properties_json, '$.source_kind') IS NOT NULL;

UPDATE blocks SET content_json = '{"rich_text":[{"type":"text","text":{"content":"May statement source log: the CFPB disclosure link was saved on June 10, with Sam Taylor as owner and the review status recorded separately from the issuer statement."}}]}' WHERE block_id = 'blk_ccmpe_fh62bn5je';
