UPDATE blocks SET content_json = '{"rich_text":[{"type":"text","text":{"content":"Housing reserve review from January 25: the bank account, rent ledger, and family-budget appointment refer to the same monthly obligation; no withdrawal was recorded."}}]}' WHERE block_id = 'blk_ccmpe_em6j6tbmz';
