UPDATE blocks SET content_json = '{"rich_text":[{"type":"text","text":{"content":"The payment meeting note links one checking entry, the issuer correspondence thread, and the calendar appointment that followed it; status remains distinct in each system."}}]}' WHERE block_id = 'blk_ccmpe_z56tfajgb';
PRAGMA foreign_keys=ON;
